import type { ExpenseRecord, InventoryMovementRecord, InventoryMovementType, PurchaseRecord, RecurringWorkflowRecord, SavedItem, Supplier, SupplierPaymentRecord } from '../types.js';
import { isArabic, t } from '../lib/i18n.js';
import { setWorkspaceDirty } from '../lib/workspace-dirty.js';
import { formatMoney } from '../lib/money.js';
import { todayIso } from '../lib/id.js';
import { allocateLandedCost, createExpense, createManualInventoryMovement, createPurchase, createPurchaseItem, createSupplier, inventoryBalances, inventoryMovementIsManual, operationsIntegritySummary, purchaseTotals, spendByCurrency, supplierSnapshotFrom, validateExpense, validatePurchase, validateSupplier } from '../lib/operations.js';
import { purchasePayableSummary, supplierPayablesByCurrency } from '../lib/payables.js';
import { ensurePayablesStyles } from '../lib/payables-style.js';
import { Supplier360LivePanel } from './Supplier360LivePanel.js';
import { EntityAuditLivePanel } from './EntityAuditLivePanel.js';
import { Button, ConfirmDialog, Icon, Input, Modal, Select, Textarea } from './UI.js';

type Tab='suppliers'|'purchases'|'expenses'|'inventory';
export type OperationsWorkspaceMode='all'|'purchasing'|'finance'|'inventory';
type ManualMovementType=Extract<InventoryMovementType,'opening'|'issue'|'adjustment'>;
type ConfirmAction=
  |{kind:'delete-supplier';supplier:Supplier}
  |{kind:'post-purchase';purchase:PurchaseRecord}
  |{kind:'delete-purchase';purchase:PurchaseRecord}
  |{kind:'delete-expense';expense:ExpenseRecord}
  |{kind:'reverse-movement';movement:InventoryMovementRecord};

interface Props{
  mode?:OperationsWorkspaceMode;inventoryView?:'all'|'balances'|'movements';focusItemId?:string;
  suppliers:Supplier[];purchases:PurchaseRecord[];supplierPayments?:SupplierPaymentRecord[];expenses:ExpenseRecord[];inventoryMovements:InventoryMovementRecord[];items:SavedItem[];defaultCurrency:string;
  recurringWorkflows?:RecurringWorkflowRecord[];onMakeRecurringPurchase?:(purchase:PurchaseRecord)=>void;onOpenRecurring?:()=>void;
  onOpenSupplierFinance?:(supplierId:string)=>void;
  onSaveSupplier:(supplier:Supplier)=>Promise<void>;onDeleteSupplier:(supplier:Supplier)=>Promise<void>;
  onSavePurchase:(purchase:PurchaseRecord)=>Promise<void>;onDeletePurchase:(purchase:PurchaseRecord)=>Promise<void>;onPostPurchase:(purchase:PurchaseRecord)=>Promise<void>;onReversePurchase:(purchase:PurchaseRecord,reason:string)=>Promise<void>;
  onSaveExpense:(expense:ExpenseRecord)=>Promise<void>;onDeleteExpense:(expense:ExpenseRecord)=>Promise<void>;
  onSaveInventoryMovement:(movement:InventoryMovementRecord)=>Promise<void>;onDeleteInventoryMovement:(movement:InventoryMovementRecord)=>Promise<void>;
}
interface State{
  tab:Tab;search:string;error:string;busy:boolean;supplierEdit:Supplier|null;supplierProfileId:string;purchaseEdit:PurchaseRecord|null;expenseEdit:ExpenseRecord|null;
  movementItemId:string;movementType:ManualMovementType;movementQuantity:string;movementDate:string;movementNote:string;movementCost:string;movementCurrency:string;
  confirmAction:ConfirmAction|null;reverseTarget:PurchaseRecord|null;reverseReason:string;
}

const currencies=['USD','EUR','SAR','TRY','AED','GBP'];
const expenseCategories=['General','Freight','Customs','Storage','Transport','Marketing','Office','Professional','Bank Fees','Other'];
function tabsForMode(mode:OperationsWorkspaceMode='all'):Tab[]{return mode==='purchasing'?['suppliers','purchases']:mode==='finance'?['expenses']:mode==='inventory'?['inventory']:['suppliers','purchases','expenses','inventory'];}
function firstTab(mode:OperationsWorkspaceMode='all'):Tab{return tabsForMode(mode)[0]!;}
function localizedStored(en:string,ar:string,fallback:string):string{return (t(en||ar,ar||en)||fallback).trim();}
function supplierLabel(supplier:Supplier):string{return localizedStored(supplier.nameEn,supplier.nameAr,t('Unnamed supplier','مورد بدون اسم'));}
function purchaseSupplierLabel(purchase:PurchaseRecord):string{return localizedStored(purchase.supplierSnapshot?.nameEn||'',purchase.supplierSnapshot?.nameAr||'',t('No supplier','بدون مورد'));}
function itemLabel(item:SavedItem):string{return [item.sku,localizedStored(item.descriptionEn,item.descriptionAr,'')].filter(Boolean).join(' · ');}
function movementItemLabel(movement:InventoryMovementRecord):string{return localizedStored(movement.itemNameEn||'',movement.itemNameAr||'',movement.sku||t('Unnamed item','صنف بدون اسم'));}
function purchaseStatusLabel(status:PurchaseRecord['status']):string{return status==='posted'?t('Posted','مرحل'):status==='reversed'?t('Reversed','معكوس'):t('Draft','مسودة');}
function payableStatusLabel(status:ReturnType<typeof purchasePayableSummary>['state']):string{return status==='paid'?t('Paid','مدفوع'):status==='partial'?t('Partially paid','مدفوع جزئيًا'):status==='overdue'?t('Overdue','متأخر'):status==='unpaid'?t('Unpaid','غير مدفوع'):status==='draft'?t('Draft commitment','التزام مسودة'):t('Reversed','معكوس');}
function expenseCategoryLabel(category:string):string{
  if(category==='General')return t('General','عام');if(category==='Freight')return t('Freight','شحن');if(category==='Customs')return t('Customs','جمارك');if(category==='Storage')return t('Storage','تخزين');if(category==='Transport')return t('Transport','نقل');if(category==='Marketing')return t('Marketing','تسويق');if(category==='Office')return t('Office','مكتب');if(category==='Professional')return t('Professional','خدمات مهنية');if(category==='Bank Fees')return t('Bank Fees','رسوم بنكية');if(category==='Other')return t('Other','أخرى');return category;
}
function movementTypeLabel(type:InventoryMovementType):string{if(type==='purchase')return t('Purchase receipt','استلام شراء');if(type==='purchase-reversal')return t('Purchase reversal','عكس شراء');if(type==='opening')return t('Opening stock','رصيد افتتاحي');if(type==='issue')return t('Stock issue','إخراج مخزون');return t('Adjustment','تسوية');}

export class OperationsPage extends React.Component<Props,State>{
  private mutationInFlight=false;
  private editorBaseline:{supplier:string|null;purchase:string|null;expense:string|null}={supplier:null,purchase:null,expense:null};
  state:State={tab:firstTab(this.props.mode),search:'',error:'',busy:false,supplierEdit:null,supplierProfileId:'',purchaseEdit:null,expenseEdit:null,movementItemId:'',movementType:'opening',movementQuantity:'',movementDate:todayIso(),movementNote:'',movementCost:'',movementCurrency:this.props.defaultCurrency||'USD',confirmAction:null,reverseTarget:null,reverseReason:''};

  componentDidMount():void{ensurePayablesStyles();window.addEventListener('lourex-create-purchase',this.handleQuickPurchase);window.addEventListener('lourex-open-expense-editor',this.handleQuickExpense);window.addEventListener('lourex-open-purchase',this.handleOpenPurchase);window.addEventListener('lourex-open-supplier',this.handleOpenSupplier); window.addEventListener('beforeunload',this.handleBeforeUnload);this.applyFocusedItem();this.syncDirtyMarker();}
  componentWillUnmount():void{window.removeEventListener('lourex-create-purchase',this.handleQuickPurchase);window.removeEventListener('lourex-open-expense-editor',this.handleQuickExpense);window.removeEventListener('lourex-open-purchase',this.handleOpenPurchase);window.removeEventListener('lourex-open-supplier',this.handleOpenSupplier);window.removeEventListener('beforeunload',this.handleBeforeUnload);setWorkspaceDirty('operations',false);}
  componentDidUpdate(prev:Props):void{if(prev.mode!==this.props.mode){const allowed=tabsForMode(this.props.mode);if(!allowed.includes(this.state.tab))this.setState({tab:firstTab(this.props.mode),search:'',error:'',supplierProfileId:''});}if(this.state.supplierProfileId&&!this.props.suppliers.some(s=>s.id===this.state.supplierProfileId))this.setState({supplierProfileId:''});if(prev.focusItemId!==this.props.focusItemId)this.applyFocusedItem();this.syncDirtyMarker();}
  private supplierPayments=():SupplierPaymentRecord[]=>this.props.supplierPayments??[];
  private hasUnsavedWorkspaceInput=():boolean=>{const supplier=this.state.supplierEdit,supplierDirty=Boolean(supplier&&JSON.stringify(supplier)!==this.editorBaseline.supplier);const purchase=this.state.purchaseEdit,purchaseDirty=Boolean(purchase&&purchase.status==='draft'&&JSON.stringify(purchase)!==this.editorBaseline.purchase);const expense=this.state.expenseEdit,expenseDirty=Boolean(expense&&JSON.stringify(expense)!==this.editorBaseline.expense);const movementDirty=Boolean(this.state.movementQuantity.trim()||this.state.movementNote.trim()||this.state.movementCost.trim());return supplierDirty||purchaseDirty||expenseDirty||movementDirty;};
  private syncDirtyMarker=()=>setWorkspaceDirty('operations',this.hasUnsavedWorkspaceInput());
  private confirmDiscardCurrent=():boolean=>!this.hasUnsavedWorkspaceInput()||window.confirm(t('Discard the unsaved changes and continue?','تجاهل التعديلات غير المحفوظة والمتابعة؟'));
  private closeEditors=()=>{if(!this.confirmDiscardCurrent())return;this.editorBaseline={supplier:null,purchase:null,expense:null};this.setState({supplierEdit:null,purchaseEdit:null,expenseEdit:null,error:''});};
  private changeTab=(tab:Tab)=>{if(tab===this.state.tab)return;if(!this.confirmDiscardCurrent())return;this.editorBaseline={supplier:null,purchase:null,expense:null};this.setState({tab,search:'',error:'',supplierEdit:null,supplierProfileId:'',purchaseEdit:null,expenseEdit:null});};
  private openSupplierProfile=(supplier:Supplier)=>{if(!this.confirmDiscardCurrent())return;this.editorBaseline={supplier:null,purchase:null,expense:null};this.setState({supplierProfileId:supplier.id,supplierEdit:null,purchaseEdit:null,expenseEdit:null,error:''});};
  private startSupplier=(supplier?:Supplier)=>{if(!this.confirmDiscardCurrent())return;const edit=supplier?structuredClone(supplier):createSupplier();this.editorBaseline={supplier:JSON.stringify(edit),purchase:null,expense:null};this.setState({supplierEdit:edit,supplierProfileId:'',purchaseEdit:null,expenseEdit:null,error:''});};
  private startExpense=(expense?:ExpenseRecord)=>{if(!this.confirmDiscardCurrent())return;const edit=expense?structuredClone(expense):createExpense(this.props.defaultCurrency);this.editorBaseline={supplier:null,purchase:null,expense:JSON.stringify(edit)};this.setState({expenseEdit:edit,supplierEdit:null,supplierProfileId:'',purchaseEdit:null,error:''});};
  private viewPurchase=(purchase:PurchaseRecord)=>{if(!this.confirmDiscardCurrent())return;const edit=structuredClone(purchase);this.editorBaseline={supplier:null,purchase:JSON.stringify(edit),expense:null};this.setState({purchaseEdit:edit,supplierEdit:null,supplierProfileId:'',expenseEdit:null,error:''});};
  private handleBeforeUnload=(event:BeforeUnloadEvent)=>{if(!this.hasUnsavedWorkspaceInput())return;event.preventDefault();event.returnValue='';};
  private applyFocusedItem=()=>{const id=this.props.focusItemId;if(!id)return;const item=this.props.items.find(entry=>entry.id===id);if(!item)return;this.setState({search:item.sku||item.descriptionEn||item.descriptionAr,movementItemId:item.id,error:''});};
  private handleOpenSupplier=(event:Event)=>{const id=(event as CustomEvent<{id?:string}>).detail?.id;const supplier=this.props.suppliers.find(row=>row.id===id);if(!supplier||this.props.mode==='finance'||this.props.mode==='inventory'||!this.confirmDiscardCurrent())return;this.setState({tab:'suppliers',search:'',error:''},()=>this.openSupplierProfile(supplier));};
  private handleOpenPurchase=(event:Event)=>{const id=String((event as CustomEvent<{id?:string}>).detail?.id||'');const purchase=this.props.purchases.find(item=>item.id===id);if(!purchase||!this.confirmDiscardCurrent())return;this.setState({tab:'purchases',search:'',error:'',supplierEdit:null,supplierProfileId:'',expenseEdit:null},()=>this.viewPurchase(purchase));};
  private handleQuickPurchase=()=>{if((this.props.mode!=='purchasing'&&this.props.mode!=='all')||!this.confirmDiscardCurrent())return;this.setState({tab:'purchases',search:'',error:'',supplierEdit:null,supplierProfileId:'',expenseEdit:null,purchaseEdit:null},()=>this.newPurchase(true));};
  private handleQuickExpense=()=>{if((this.props.mode!=='finance'&&this.props.mode!=='all')||!this.confirmDiscardCurrent())return;const edit=createExpense(this.props.defaultCurrency);this.editorBaseline={supplier:null,purchase:null,expense:JSON.stringify(edit)};this.setState({tab:'expenses',expenseEdit:edit,supplierEdit:null,supplierProfileId:'',purchaseEdit:null,search:'',error:''});};
  private fail=(error:unknown)=>this.setState({error:error instanceof Error?error.message:String(error)});
  private clearError=()=>this.setState({error:''});
  private visible=(...values:string[])=>{const q=this.state.search.trim().toLowerCase();return !q||values.join(' ').toLowerCase().includes(q);};
  private runMutation=async(work:()=>Promise<void>):Promise<boolean>=>{if(this.mutationInFlight)return false;this.mutationInFlight=true;this.setState({busy:true,error:''});try{await work();return true;}catch(e){this.fail(e);return false;}finally{this.mutationInFlight=false;this.setState({busy:false});}};
  private saveSupplier=async()=>{const supplier=this.state.supplierEdit;if(!supplier||this.mutationInFlight)return;const errors=validateSupplier(supplier);if(errors.length){this.setState({error:errors[0]??t('Validation failed.','فشل التحقق.')});return;}await this.runMutation(async()=>{await this.props.onSaveSupplier({...supplier,defaultCurrency:supplier.defaultCurrency.trim().toUpperCase(),updatedAt:new Date().toISOString()});this.setState({supplierEdit:null,error:''});});};
  private deleteSupplier=(supplier:Supplier)=>{if(this.mutationInFlight)return;this.setState({confirmAction:{kind:'delete-supplier',supplier},error:''});};
  private newPurchase=(confirmed=false)=>{if(this.mutationInFlight||(!confirmed&&!this.confirmDiscardCurrent()))return;const purchase=createPurchase(this.props.purchases,this.props.suppliers,this.props.defaultCurrency);purchase.items=[createPurchaseItem()];this.editorBaseline={supplier:null,purchase:JSON.stringify(purchase),expense:null};this.setState({purchaseEdit:purchase,supplierEdit:null,supplierProfileId:'',expenseEdit:null,error:''});};
  private newPurchaseForSupplier=(supplier:Supplier)=>{if(this.mutationInFlight||!this.confirmDiscardCurrent())return;const purchase=createPurchase(this.props.purchases,this.props.suppliers,supplier.defaultCurrency||this.props.defaultCurrency);purchase.supplierSnapshot=supplierSnapshotFrom(supplier);purchase.currency=supplier.defaultCurrency||purchase.currency;purchase.items=[createPurchaseItem()];this.editorBaseline={supplier:null,purchase:JSON.stringify(purchase),expense:null};this.setState({tab:'purchases',purchaseEdit:purchase,supplierEdit:null,supplierProfileId:'',expenseEdit:null,search:'',error:''});};
  private showSupplierPurchaseHistory=(supplier:Supplier)=>{if(!this.confirmDiscardCurrent())return;this.editorBaseline={supplier:null,purchase:null,expense:null};this.setState({tab:'purchases',purchaseEdit:null,supplierEdit:null,supplierProfileId:'',expenseEdit:null,search:supplierLabel(supplier),error:''});};
  private choosePurchaseSupplier=(supplierId:string)=>this.setState(state=>{if(!state.purchaseEdit)return null as any;const supplier=this.props.suppliers.find(item=>item.id===supplierId);return{purchaseEdit:{...state.purchaseEdit,supplierSnapshot:supplier?supplierSnapshotFrom(supplier):null,currency:supplier?.defaultCurrency||state.purchaseEdit.currency}} as any;});
  private updatePurchaseItem=(id:string,patch:Partial<PurchaseRecord['items'][number]>)=>this.setState(state=>state.purchaseEdit?({purchaseEdit:{...state.purchaseEdit,items:state.purchaseEdit.items.map(item=>item.id===id?{...item,...patch}:item)}} as any):null as any);
  private chooseSavedItem=(lineId:string,itemId:string)=>{const saved=this.props.items.find(item=>item.id===itemId);if(!saved){this.updatePurchaseItem(lineId,{savedItemId:'',sku:''});return;}this.updatePurchaseItem(lineId,{savedItemId:saved.id,sku:saved.sku??'',descriptionEn:saved.descriptionEn,descriptionAr:saved.descriptionAr,unit:saved.unit||'PCS',unitCost:saved.lastUnitCost??''});};
  private addPurchaseItem=()=>this.setState(state=>state.purchaseEdit?({purchaseEdit:{...state.purchaseEdit,items:[...state.purchaseEdit.items,createPurchaseItem()]}} as any):null as any);
  private removePurchaseItem=(id:string)=>this.setState(state=>state.purchaseEdit?({purchaseEdit:{...state.purchaseEdit,items:state.purchaseEdit.items.filter(item=>item.id!==id)}} as any):null as any);
  private savePurchase=async()=>{const purchase=this.state.purchaseEdit;if(!purchase||this.mutationInFlight)return;const errors=validatePurchase(purchase,this.props.items);if(errors.length){this.setState({error:errors[0]??t('Validation failed.','فشل التحقق.')});return;}await this.runMutation(async()=>{await this.props.onSavePurchase({...purchase,currency:purchase.currency.trim().toUpperCase(),updatedAt:new Date().toISOString()});this.setState({purchaseEdit:null,error:''});});};
  private postPurchase=()=>{const purchase=this.state.purchaseEdit;if(!purchase||this.mutationInFlight)return;const errors=validatePurchase(purchase,this.props.items);if(errors.length){this.setState({error:errors[0]??t('Validation failed.','فشل التحقق.')});return;}this.setState({confirmAction:{kind:'post-purchase',purchase:structuredClone(purchase)},error:''});};
  private deletePurchase=(purchase:PurchaseRecord)=>{if(this.mutationInFlight)return;if(purchase.status!=='draft'){this.setState({error:t('Only draft purchases can be deleted.','يمكن حذف مسودات الشراء فقط.')});return;}this.setState({confirmAction:{kind:'delete-purchase',purchase},error:''});};
  private reversePurchase=(purchase:PurchaseRecord)=>{if(this.mutationInFlight)return;this.setState({reverseTarget:purchase,reverseReason:'',error:''});};
  private saveExpense=async()=>{const expense=this.state.expenseEdit;if(!expense||this.mutationInFlight)return;const errors=validateExpense(expense);if(errors.length){this.setState({error:errors[0]??t('Validation failed.','فشل التحقق.')});return;}await this.runMutation(async()=>{await this.props.onSaveExpense({...expense,currency:expense.currency.trim().toUpperCase(),updatedAt:new Date().toISOString()});this.setState({expenseEdit:null,error:''});});};
  private deleteExpense=(expense:ExpenseRecord)=>{if(this.mutationInFlight)return;this.setState({confirmAction:{kind:'delete-expense',expense},error:''});};
  private saveMovement=async()=>{const item=this.props.items.find(entry=>entry.id===this.state.movementItemId);if(!item){this.setState({error:t('Choose a saved item first.','اختر صنفًا محفوظًا أولًا.')});return;}if(this.mutationInFlight)return;await this.runMutation(async()=>{const movement=createManualInventoryMovement(item,this.state.movementType,this.state.movementQuantity,this.state.movementDate,this.state.movementNote,this.state.movementCost,this.state.movementCurrency);await this.props.onSaveInventoryMovement(movement);this.setState({movementQuantity:'',movementNote:'',movementCost:'',error:''});});};
  private deleteMovement=(movement:InventoryMovementRecord)=>{if(this.mutationInFlight)return;if(!inventoryMovementIsManual(movement)){this.setState({error:t('Purchase-generated inventory movements cannot be deleted. Reverse the purchase instead.','لا يمكن حذف حركات المخزون الناتجة عن شراء. اعكس الشراء بدلًا من ذلك.')});return;}this.setState({confirmAction:{kind:'reverse-movement',movement},error:''});};

  private confirmAction=async()=>{
    const action=this.state.confirmAction;if(!action||this.mutationInFlight)return;
    this.setState({confirmAction:null});
    if(action.kind==='delete-supplier'){await this.runMutation(async()=>{await this.props.onDeleteSupplier(action.supplier);if(this.state.supplierEdit?.id===action.supplier.id||this.state.supplierProfileId===action.supplier.id)this.setState({supplierEdit:null,supplierProfileId:''});});return;}
    if(action.kind==='post-purchase'){await this.runMutation(async()=>{await this.props.onPostPurchase({...action.purchase,currency:action.purchase.currency.trim().toUpperCase()});this.setState({purchaseEdit:null,error:''});});return;}
    if(action.kind==='delete-purchase'){await this.runMutation(async()=>{await this.props.onDeletePurchase(action.purchase);if(this.state.purchaseEdit?.id===action.purchase.id)this.setState({purchaseEdit:null});});return;}
    if(action.kind==='delete-expense'){await this.runMutation(async()=>{await this.props.onDeleteExpense(action.expense);if(this.state.expenseEdit?.id===action.expense.id)this.setState({expenseEdit:null});});return;}
    await this.runMutation(async()=>{await this.props.onDeleteInventoryMovement(action.movement);});
  };
  private confirmReversePurchase=async()=>{
    const purchase=this.state.reverseTarget,reason=this.state.reverseReason.trim();if(!purchase||!reason||this.mutationInFlight)return;
    this.setState({reverseTarget:null,reverseReason:''});
    await this.runMutation(async()=>{await this.props.onReversePurchase(purchase,reason);if(this.state.purchaseEdit?.id===purchase.id)this.setState({purchaseEdit:null,error:''});});
  };
  private renderActionDialogs=():any=>{
    const action=this.state.confirmAction;
    let title='',message='',confirmLabel='',destructive=true;
    if(action?.kind==='delete-supplier'){title=t('Delete supplier?','حذف المورد؟');message=t(`Delete ${supplierLabel(action.supplier)} from the supplier list? Historical purchases keep their saved supplier snapshot.`,`حذف ${supplierLabel(action.supplier)} من قائمة الموردين؟ ستبقى بيانات المورد المحفوظة داخل المشتريات التاريخية.`);confirmLabel=t('Delete supplier','حذف المورد');}
    else if(action?.kind==='post-purchase'){title=t('Post purchase?','ترحيل عملية الشراء؟');message=t('Stock receipt movements and landed costs will be recorded and this purchase will become read-only. The posted amount becomes a supplier payable until payments are recorded in Finance.','سيتم تسجيل حركات استلام المخزون وتكاليف الوصول وستصبح عملية الشراء للقراءة فقط. ويصبح المبلغ المرحل مستحقًا للمورد حتى تُسجل المدفوعات في المالية.');confirmLabel=t('Post purchase','ترحيل الشراء');destructive=false;}
    else if(action?.kind==='delete-purchase'){title=t('Delete purchase draft?','حذف مسودة الشراء؟');message=t(`Delete ${action.purchase.number}? This draft has not been posted to inventory.`,`حذف ${action.purchase.number}؟ هذه المسودة لم تُرحّل إلى المخزون.`);confirmLabel=t('Delete draft','حذف المسودة');}
    else if(action?.kind==='delete-expense'){title=t('Delete expense?','حذف المصروف؟');message=t('This removes the operating expense from financial analysis.','سيتم حذف المصروف التشغيلي من التحليل المالي.');confirmLabel=t('Delete expense','حذف المصروف');}
    else if(action?.kind==='reverse-movement'){title=t('Reverse manual inventory movement?','عكس حركة المخزون اليدوية؟');message=t('A reversing entry will be recorded while the original movement remains in the audit history.','سيتم تسجيل حركة عكسية مع بقاء الحركة الأصلية محفوظة في سجل التدقيق.');confirmLabel=t('Reverse movement','عكس الحركة');}
    return <>
      <ConfirmDialog open={Boolean(action)} title={title} message={message} confirmLabel={confirmLabel} destructive={destructive} onCancel={()=>this.setState({confirmAction:null})} onConfirm={()=>void this.confirmAction()}/>
      <Modal open={Boolean(this.state.reverseTarget)} title={t('Reverse posted purchase','عكس عملية شراء مرحلة')} size="sm" onClose={()=>{if(!this.state.busy)this.setState({reverseTarget:null,reverseReason:''});}} footer={<div className="modal-footer-actions"><Button disabled={this.state.busy} onClick={()=>this.setState({reverseTarget:null,reverseReason:''})}>{t('Cancel','إلغاء')}</Button><Button variant="danger" disabled={this.state.busy||!this.state.reverseReason.trim()} onClick={()=>void this.confirmReversePurchase()}>{this.state.busy?t('Working…','جارٍ التنفيذ…'):t('Reverse purchase','عكس الشراء')}</Button></div>}>
        <p className="modal-message">{t('Reversing creates inventory reversal movements and keeps the posted purchase in history. Enter a reason for the audit trail.','العكس ينشئ حركات عكس للمخزون ويبقي عملية الشراء المرحلة في السجل. أدخل سببًا ليظهر في سجل التدقيق.')}</p>
        <label className="ta-ops-reverse-reason"><span>{t('Reason','السبب')}</span><Textarea autoFocus rows={3} value={this.state.reverseReason} onChange={(e:any)=>this.setState({reverseReason:e.target.value})} placeholder={t('Why is this purchase being reversed?','ما سبب عكس عملية الشراء؟')}/></label>
      </Modal>
    </>;
  };

  private heading(){const mode=this.props.mode??'all';return mode==='purchasing'?{eyebrow:t('Procurement','التوريد'),title:t('Purchasing','المشتريات'),description:t('Suppliers and purchase records in one clear purchasing workspace. Supplier payment balances stay in Finance.','الموردون وسجلات الشراء في مساحة مشتريات واحدة واضحة. وتبقى أرصدة مدفوعات الموردين في المالية.')} : mode==='finance'?{eyebrow:t('Finance','المالية'),title:t('Expenses','المصروفات'),description:t('Record and review operating expenses without mixing them into purchasing.','سجّل وراجع المصروفات التشغيلية بدون خلطها مع المشتريات.')} : mode==='inventory'?{eyebrow:t('Products & Inventory','المنتجات والمخزون'),title:t('Inventory','المخزون'),description:t('Current stock, manual movements and auditable inventory history.','الرصيد الحالي والحركات اليدوية وسجل مخزون قابل للتدقيق.')}:{eyebrow:t('Purchasing & Cost Control','المشتريات وضبط التكلفة'),title:t('Operations','العمليات'),description:t('Suppliers, purchases, operating expenses, landed cost and a simple auditable inventory ledger.','الموردون والمشتريات والمصروفات التشغيلية وتكلفة الوصول وسجل مخزون بسيط وقابل للتدقيق.')};}

  private renderSummary():any{
    const mode=this.props.mode??'all',integrity=operationsIntegritySummary(this.props.purchases,this.props.expenses,this.props.inventoryMovements);
    if(mode!=='all'){const invalid=mode==='purchasing'?integrity.invalidPurchases:mode==='finance'?integrity.invalidExpenses:integrity.invalidMovements;if(!invalid)return null;const noun=mode==='purchasing'?t('purchase records','سجلات مشتريات'):mode==='finance'?t('expense records','سجلات مصروفات'):t('inventory movements','حركات مخزون');return <div className="ta-ops-integrity is-danger" role="status"><span><Icon name="alert"/></span><div><strong>{t('Accounting integrity warning','تنبيه سلامة البيانات المحاسبية')}</strong><small>{t(`${invalid} ${noun} are excluded from totals until corrected.`,`${invalid} ${noun} مستبعدة من الإجماليات حتى يتم تصحيحها.`)}</small></div></div>;}
    const spend=spendByCurrency(this.props.purchases,this.props.expenses);
    return <><section className="ta-ops-metrics"><div><span className="ta-ops-metric-icon"><Icon name="users"/></span><span><small>{t('Suppliers','الموردون')}</small><strong>{this.props.suppliers.length}</strong></span></div><div><span className="ta-ops-metric-icon"><Icon name="backup"/></span><span><small>{t('Posted purchases','مشتريات مرحلة')}</small><strong>{this.props.purchases.filter(p=>p.status==='posted').length}</strong></span></div><div><span className="ta-ops-metric-icon"><Icon name="invoice"/></span><span><small>{t('Expenses','المصروفات')}</small><strong>{this.props.expenses.length}</strong></span></div><div className="ta-ops-spend"><span className="ta-ops-metric-icon"><Icon name="chart"/></span><span><small>{t('Spend by currency','الإنفاق حسب العملة')}</small>{spend.length?spend.slice(0,3).map(row=><strong key={row.currency}>{formatMoney(row.total,row.currency)}</strong>):<strong>—</strong>}</span></div></section>{integrity.totalInvalid?<div className="ta-ops-integrity is-danger" role="status"><span><Icon name="alert"/></span><div><strong>{t('Accounting integrity warning','تنبيه سلامة البيانات المحاسبية')}</strong><small>{t(`${integrity.totalInvalid} historical Operations record(s) are excluded from accounting or inventory totals until corrected. Purchases: ${integrity.invalidPurchases} · Expenses: ${integrity.invalidExpenses} · Inventory: ${integrity.invalidMovements}`,`تم استبعاد ${integrity.totalInvalid} سجل تاريخي في العمليات من إجماليات المحاسبة أو المخزون حتى يتم تصحيحه. المشتريات: ${integrity.invalidPurchases} · المصروفات: ${integrity.invalidExpenses} · المخزون: ${integrity.invalidMovements}`)}</small></div></div>:null}</>;
  }

  private panelHead=(eyebrow:string,title:string,description:string,action?:any)=><header className="ta-ops-panel-head"><div><small>{eyebrow}</small><h2>{title}</h2><p>{description}</p></div>{action}</header>;

  private renderSuppliers():any{
    const list=this.props.suppliers.filter(s=>this.visible(s.nameEn,s.nameAr,s.contactPerson,s.country,s.phone,s.email)),edit=this.state.supplierEdit,profile=this.props.suppliers.find(s=>s.id===this.state.supplierProfileId)||null;
    return <div className="ta-ops-split"><section className="ta-ops-list-card">{this.panelHead(t('Counterparties','الأطراف'),t('Suppliers','الموردون'),t('Reusable purchasing counterparties. Historical purchases keep their own supplier snapshot.','جهات شراء محفوظة، مع بقاء بيانات المورد التاريخية داخل كل عملية شراء.'),<Button icon="plus" variant="primary" disabled={this.state.busy} onClick={()=>this.startSupplier()}>{t('New Supplier','مورد جديد')}</Button>)}<div className="ta-ops-list">{list.length?list.map(s=><article key={s.id} className={`ta-ops-row ${profile?.id===s.id?'is-selected':''}`}><span className="ta-ops-row-icon"><Icon name="users"/></span><div className="ta-ops-row-copy"><strong>{supplierLabel(s)}</strong><small>{[s.contactPerson,s.country,s.defaultCurrency].filter(Boolean).join(' · ')||t('Supplier profile','ملف المورد')}</small></div><div className="ta-ops-row-actions"><button disabled={this.state.busy} onClick={()=>this.openSupplierProfile(s)}>{t('View 360','عرض 360')}</button><button disabled={this.state.busy} onClick={()=>this.newPurchaseForSupplier(s)}>{t('New Purchase','شراء جديد')}</button><button disabled={this.state.busy} onClick={()=>this.showSupplierPurchaseHistory(s)}>{t('History','السجل')}</button><button disabled={this.state.busy} onClick={()=>this.startSupplier(s)}>{t('Edit','تعديل')}</button><button disabled={this.state.busy} className="is-danger" onClick={()=>this.deleteSupplier(s)}>{t('Delete','حذف')}</button></div></article>):this.emptyState('users',t('No suppliers yet.','لا يوجد موردون بعد.'),t('Create a supplier once, then reuse it across purchases.','أنشئ المورد مرة واحدة ثم أعد استخدامه في المشتريات.'))}</div></section>{profile?this.renderSupplierProfile(profile):edit?this.renderSupplierEditor(edit):null}</div>;
  }

  private renderSupplierProfile=(supplier:Supplier)=>{
    const balances=supplierPayablesByCurrency(this.props.purchases,this.supplierPayments(),todayIso(),supplier.id);
    return <aside className="ta-ops-editor lx-supplier-profile"><header className="ta-ops-editor-head"><div><small>{t('Supplier relationship','علاقة المورد')}</small><h2>{supplierLabel(supplier)}</h2><span>{[supplier.contactPerson,supplier.country,supplier.defaultCurrency].filter(Boolean).join(' · ')}</span></div><button type="button" aria-label={t('Close Supplier 360','إغلاق ملف المورد 360')} onClick={()=>this.setState({supplierProfileId:''})}><Icon name="x"/></button></header><div className="ta-ops-editor-scroll"><section className="lx-supplier-profile-facts"><div><small>{t('Contact','جهة الاتصال')}</small><strong>{supplier.contactPerson||'—'}</strong></div><div><small>{t('Phone','الهاتف')}</small><strong dir="ltr">{supplier.phone||'—'}</strong></div><div><small>{t('Email','البريد')}</small><strong dir="ltr">{supplier.email||'—'}</strong></div><div><small>{t('Payment terms','شروط الدفع')}</small><strong>{supplier.paymentTerms||'—'}</strong></div></section><section className="lx-supplier-ap-summary"><div className="lx-supplier-ap-summary-head"><div><small>{t('Supplier finance','مالية المورد')}</small><strong>{t('Payables summary','ملخص المستحقات')}</strong></div>{this.props.onOpenSupplierFinance?<Button icon="wallet" onClick={()=>this.props.onOpenSupplierFinance?.(supplier.id)}>{t('Open in Finance','فتح في المالية')}</Button>:null}</div>{balances.length?<div className="lx-supplier-ap-summary-grid">{balances.map(row=><span key={row.currency}>{row.currency}<strong>{t('Remaining','المتبقي')}: {formatMoney(row.remaining,row.currency)}</strong><small>{t('Paid','المدفوع')}: {formatMoney(row.paid,row.currency)} · {t('Overdue','المتأخر')}: {formatMoney(row.overdue,row.currency)}</small></span>)}</div>:<small>{t('No posted payable balance for this supplier.','لا يوجد رصيد مستحق مرحل لهذا المورد.')}</small>}</section><Supplier360LivePanel supplier={supplier}/></div><footer className="ta-ops-editor-actions"><Button disabled={this.state.busy} onClick={()=>this.startSupplier(supplier)}>{t('Edit Supplier','تعديل المورد')}</Button><Button icon="plus" variant="primary" disabled={this.state.busy} onClick={()=>this.newPurchaseForSupplier(supplier)}>{t('New Purchase','شراء جديد')}</Button></footer></aside>;
  };

  private renderSupplierEditor=(edit:Supplier)=> <aside className="ta-ops-editor"><header className="ta-ops-editor-head"><div><small>{t('Supplier profile','ملف المورد')}</small><h2>{edit.createdAt===edit.updatedAt?t('New Supplier','مورد جديد'):t('Edit Supplier','تعديل المورد')}</h2></div><button type="button" disabled={this.state.busy} aria-label={t('Close editor','إغلاق المحرر')} onClick={this.closeEditors}><Icon name="x"/></button></header><div className="ta-ops-editor-scroll"><div className="ta-ops-form-grid" dir={isArabic()?'rtl':'ltr'}>{isArabic()?<><label>{t('Name AR','الاسم AR')}<Input autoFocus dir="rtl" value={edit.nameAr} onChange={(e:any)=>this.setState({supplierEdit:{...edit,nameAr:e.target.value}})}/></label><label>{t('Name EN','الاسم EN')}<Input value={edit.nameEn} onChange={(e:any)=>this.setState({supplierEdit:{...edit,nameEn:e.target.value}})}/></label></>:<><label>{t('Name EN','الاسم EN')}<Input autoFocus value={edit.nameEn} onChange={(e:any)=>this.setState({supplierEdit:{...edit,nameEn:e.target.value}})}/></label><label>{t('Name AR','الاسم AR')}<Input dir="rtl" value={edit.nameAr} onChange={(e:any)=>this.setState({supplierEdit:{...edit,nameAr:e.target.value}})}/></label></>}<label>{t('Contact person','جهة الاتصال')}<Input value={edit.contactPerson} onChange={(e:any)=>this.setState({supplierEdit:{...edit,contactPerson:e.target.value}})}/></label><label>{t('Country','الدولة')}<Input value={edit.country} onChange={(e:any)=>this.setState({supplierEdit:{...edit,country:e.target.value}})}/></label><label>{t('City','المدينة')}<Input value={edit.city} onChange={(e:any)=>this.setState({supplierEdit:{...edit,city:e.target.value}})}/></label><label>{t('Phone','الهاتف')}<Input value={edit.phone} onChange={(e:any)=>this.setState({supplierEdit:{...edit,phone:e.target.value}})}/></label><label>{t('Email','البريد')}<Input type="email" value={edit.email} onChange={(e:any)=>this.setState({supplierEdit:{...edit,email:e.target.value}})}/></label><label>{t('Default currency','العملة الافتراضية')}<Input list="operations-currencies" value={edit.defaultCurrency} onChange={(e:any)=>this.setState({supplierEdit:{...edit,defaultCurrency:e.target.value.toUpperCase()}})}/></label><label className="is-wide">{t('Address','العنوان')}<Input value={edit.address} onChange={(e:any)=>this.setState({supplierEdit:{...edit,address:e.target.value}})}/></label><label>{t('VAT / Tax No.','رقم الضريبة')}<Input value={edit.vatTaxNumber} onChange={(e:any)=>this.setState({supplierEdit:{...edit,vatTaxNumber:e.target.value}})}/></label><label>{t('Commercial Registration','السجل التجاري')}<Input value={edit.commercialRegistration} onChange={(e:any)=>this.setState({supplierEdit:{...edit,commercialRegistration:e.target.value}})}/></label><label className="is-wide">{t('Payment terms','شروط الدفع')}<Input value={edit.paymentTerms} onChange={(e:any)=>this.setState({supplierEdit:{...edit,paymentTerms:e.target.value}})}/></label><label className="is-wide">{t('Notes','ملاحظات')}<Textarea value={edit.notes} onChange={(e:any)=>this.setState({supplierEdit:{...edit,notes:e.target.value}})}/></label></div></div><footer className="ta-ops-editor-actions"><Button disabled={this.state.busy} onClick={this.closeEditors}>{t('Cancel','إلغاء')}</Button><Button icon="save" variant="primary" disabled={this.state.busy} onClick={()=>void this.saveSupplier()}>{this.state.busy?t('Saving…','جارٍ الحفظ…'):t('Save Supplier','حفظ المورد')}</Button></footer></aside>;

  private renderPurchases():any{
    const list=[...this.props.purchases].sort((a,b)=>b.date.localeCompare(a.date)||b.updatedAt.localeCompare(a.updatedAt)).filter(p=>this.visible(p.number,purchaseSupplierLabel(p),p.supplierSnapshot?.nameEn||'',p.supplierSnapshot?.nameAr||'',p.currency,p.status,purchaseStatusLabel(p.status))),edit=this.state.purchaseEdit;
    return <div className="ta-ops-split ta-ops-purchase-split"><section className="ta-ops-list-card">{this.panelHead(t('Procurement','التوريد'),t('Purchases','المشتريات'),t('Post a purchase only when received. Posting creates stock receipt movements and a supplier payable in Finance.','رحّل الشراء عند الاستلام فقط؛ الترحيل ينشئ حركات استلام للمخزون ومستحقًا للمورد في المالية.'),<div className="lx-recurring-head-actions">{this.props.onOpenRecurring?<Button onClick={()=>this.props.onOpenRecurring?.()}>{t('Recurring','المتكرر')}</Button>:null}<Button icon="plus" variant="primary" disabled={!this.props.suppliers.length||this.state.busy} onClick={()=>this.newPurchase()}>{t('New Purchase','شراء جديد')}</Button></div>)}{!this.props.suppliers.length?<div className="ta-ops-callout">{t('Add a supplier before creating a purchase.','أضف موردًا قبل إنشاء عملية شراء.')}</div>:null}<div className="ta-ops-list">{list.length?list.map(p=>{const rowTotals=purchaseTotals(p);const payable=purchasePayableSummary(p,this.supplierPayments());return <article key={p.id} className="ta-ops-row"><span className="ta-ops-row-icon"><Icon name="backup"/></span><div className="ta-ops-row-copy"><strong>{p.number}</strong><small>{purchaseSupplierLabel(p)} · {p.date} · {formatMoney(rowTotals.landedTotal,p.currency)}</small><small>{p.status==='draft'?t('Draft commitment — no payable posted yet','التزام مسودة — لم يُرحّل مستحق بعد'):p.status==='posted'?`${t('Due','الاستحقاق')}: ${p.dueDate} · ${payableStatusLabel(payable.state)} · ${t('Remaining','المتبقي')}: ${formatMoney(payable.remaining,payable.currency)}`:t('Reversed — no active payable','معكوس — لا يوجد مستحق فعال')}</small></div><span className={`ta-ops-status is-${p.status}`}>{purchaseStatusLabel(p.status)}</span><div className="ta-ops-row-actions"><button disabled={this.state.busy} onClick={()=>this.viewPurchase(p)}>{t('View','عرض')}</button>{this.props.onMakeRecurringPurchase&&p.status!=='reversed'?<button disabled={this.state.busy} onClick={()=>this.props.onMakeRecurringPurchase?.(p)}>{t('Make recurring','تكرار')}</button>:null}{p.status==='posted'&&this.props.onOpenSupplierFinance&&p.supplierSnapshot?.sourceSupplierId?<button disabled={this.state.busy} onClick={()=>this.props.onOpenSupplierFinance?.(p.supplierSnapshot!.sourceSupplierId)}>{t('Finance','المالية')}</button>:null}{p.status==='draft'?<button disabled={this.state.busy} className="is-danger" onClick={()=>this.deletePurchase(p)}>{t('Delete','حذف')}</button>:p.status==='posted'?<button disabled={this.state.busy} className="is-danger" onClick={()=>this.reversePurchase(p)}>{t('Reverse','عكس')}</button>:null}</div></article>}):this.emptyState('backup',t('No purchases yet.','لا توجد مشتريات بعد.'),t('Purchase records will appear here after you create them.','ستظهر سجلات الشراء هنا بعد إنشائها.'))}</div></section>{edit?this.renderPurchaseEditor(edit):null}</div>;
  }

  private renderPurchaseEditor=(edit:PurchaseRecord)=>{
    const totals=purchaseTotals(edit),allocated=allocateLandedCost(edit),payable=purchasePayableSummary(edit,this.supplierPayments());
    return <aside className="ta-ops-editor ta-ops-purchase-editor"><header className="ta-ops-editor-head"><div><small>{t('Purchase record','سجل الشراء')}</small><h2>{edit.number}</h2><span className={`ta-ops-status is-${edit.status}`}>{purchaseStatusLabel(edit.status)}</span></div><button type="button" disabled={this.state.busy} aria-label={t('Close editor','إغلاق المحرر')} onClick={this.closeEditors}><Icon name="x"/></button></header>{edit.status==='reversed'?<div className="ta-ops-integrity is-danger"><span><Icon name="alert"/></span><div><strong>{t('Purchase reversed','تم عكس الشراء')}</strong><small>{edit.reverseReason}</small></div></div>:null}{edit.status==='posted'?<div className="lx-supplier-ap-summary"><div className="lx-supplier-ap-summary-head"><div><small>{t('Supplier payable','مستحق المورد')}</small><strong>{payableStatusLabel(payable.state)}</strong></div>{this.props.onOpenSupplierFinance&&edit.supplierSnapshot?.sourceSupplierId?<Button icon="wallet" onClick={()=>this.props.onOpenSupplierFinance?.(edit.supplierSnapshot!.sourceSupplierId)}>{t('Open in Finance','فتح في المالية')}</Button>:null}</div><div className="lx-supplier-ap-summary-grid"><span>{t('Total','الإجمالي')}<strong>{formatMoney(payable.total,payable.currency)}</strong></span><span>{t('Paid','المدفوع')}<strong>{formatMoney(payable.paid,payable.currency)}</strong></span><span>{t('Remaining','المتبقي')}<strong>{formatMoney(payable.remaining,payable.currency)}</strong></span><span>{t('Due date','تاريخ الاستحقاق')}<strong>{edit.dueDate}</strong></span></div></div>:null}<div className="ta-ops-editor-scroll"><fieldset disabled={edit.status!=='draft'||this.state.busy}><section className="ta-ops-form-section"><header><span>01</span><div><strong>{t('Purchase identity','بيانات الشراء')}</strong><small>{t('Supplier, purchase date, due date and currency','المورد وتاريخ الشراء والاستحقاق والعملة')}</small></div></header><div className="ta-ops-form-grid"><label>{t('Purchase No.','رقم الشراء')}<Input value={edit.number} onChange={(e:any)=>this.setState({purchaseEdit:{...edit,number:e.target.value}})}/></label><label>{t('Purchase date','تاريخ الشراء')}<Input type="date" value={edit.date} onChange={(e:any)=>this.setState({purchaseEdit:{...edit,date:e.target.value,dueDate:edit.dueDate<e.target.value?e.target.value:edit.dueDate}})}/></label><label>{t('Due date','تاريخ الاستحقاق')}<Input type="date" value={edit.dueDate} onChange={(e:any)=>this.setState({purchaseEdit:{...edit,dueDate:e.target.value}})}/></label><label>{t('Supplier','المورد')}<Select value={edit.supplierSnapshot?.sourceSupplierId??''} onChange={(e:any)=>this.choosePurchaseSupplier(e.target.value)}><option value="">{t('Choose supplier','اختر المورد')}</option>{this.props.suppliers.map(s=><option key={s.id} value={s.id}>{supplierLabel(s)}</option>)}</Select></label><label>{t('Currency','العملة')}<Input list="operations-currencies" value={edit.currency} onChange={(e:any)=>this.setState({purchaseEdit:{...edit,currency:e.target.value.toUpperCase()}})}/></label></div></section>
      <section className="ta-ops-form-section"><header><span>02</span><div><strong>{t('Items','الأصناف')}</strong><small>{t('Purchased quantities and unit costs','الكميات المشتراة وتكاليف الوحدة')}</small></div><Button icon="plus" onClick={this.addPurchaseItem}>{t('Add Item','إضافة صنف')}</Button></header><div className="ta-purchase-items">{edit.items.map((line,index)=>{const landed=allocated.items[index]?.landedUnitCost||'';return <article className="ta-purchase-item" key={line.id}><header><strong>{t(`Item ${index+1}`,`الصنف ${index+1}`)}</strong><button type="button" aria-label={t('Remove item','حذف الصنف')} onClick={()=>this.removePurchaseItem(line.id)}>×</button></header><div className="ta-ops-form-grid"><label>{t('Saved item','الصنف المحفوظ')}<Select value={line.savedItemId} onChange={(e:any)=>this.chooseSavedItem(line.id,e.target.value)}><option value="">{t('Unlinked / service','غير مرتبط / خدمة')}</option>{this.props.items.map(item=><option key={item.id} value={item.id}>{itemLabel(item)}</option>)}</Select></label><label>{t('SKU','SKU')}<Input value={line.sku} onChange={(e:any)=>this.updatePurchaseItem(line.id,{sku:e.target.value})}/></label><label className="is-wide">{t('Description EN','الوصف EN')}<Input value={line.descriptionEn} onChange={(e:any)=>this.updatePurchaseItem(line.id,{descriptionEn:e.target.value})}/></label><label className="is-wide">{t('Description AR','الوصف AR')}<Input dir="rtl" value={line.descriptionAr} onChange={(e:any)=>this.updatePurchaseItem(line.id,{descriptionAr:e.target.value})}/></label><label>{t('Quantity','الكمية')}<Input inputMode="decimal" value={line.quantity} onChange={(e:any)=>this.updatePurchaseItem(line.id,{quantity:e.target.value})}/></label><label>{t('Unit','الوحدة')}<Input value={line.unit} onChange={(e:any)=>this.updatePurchaseItem(line.id,{unit:e.target.value})}/></label><label>{t('Unit cost','تكلفة الوحدة')}<Input inputMode="decimal" value={line.unitCost} onChange={(e:any)=>this.updatePurchaseItem(line.id,{unitCost:e.target.value})}/></label><label>{t('Landed unit cost','تكلفة الوحدة بعد الوصول')}<Input readOnly value={landed}/></label></div></article>;})}</div></section>
      <section className="ta-ops-form-section"><header><span>03</span><div><strong>{t('Landed costs','تكاليف الوصول')}</strong><small>{t('Freight, customs and other acquisition costs','الشحن والجمارك وتكاليف الاقتناء الأخرى')}</small></div></header><div className="ta-ops-form-grid"><label>{t('Freight','الشحن')}<Input inputMode="decimal" value={edit.freight} onChange={(e:any)=>this.setState({purchaseEdit:{...edit,freight:e.target.value}})}/></label><label>{t('Duty / Customs','الجمارك')}<Input inputMode="decimal" value={edit.duty} onChange={(e:any)=>this.setState({purchaseEdit:{...edit,duty:e.target.value}})}/></label><label>{t('Other landed costs','تكاليف وصول أخرى')}<Input inputMode="decimal" value={edit.otherCosts} onChange={(e:any)=>this.setState({purchaseEdit:{...edit,otherCosts:e.target.value}})}/></label><label className="is-wide">{t('Notes','ملاحظات')}<Textarea value={edit.notes} onChange={(e:any)=>this.setState({purchaseEdit:{...edit,notes:e.target.value}})}/></label></div></section></fieldset>{this.props.purchases.some(item=>item.id===edit.id)?<EntityAuditLivePanel entityType="purchase" entityId={edit.id} title={t('Purchase activity','نشاط الشراء')}/>:null}</div>
      <div className="ta-purchase-totals"><span>{t('Items','الأصناف')} <strong>{formatMoney(totals.subtotal,edit.currency)}</strong></span><span>{t('Landed total','إجمالي تكلفة الوصول')} <strong>{formatMoney(totals.landedTotal,edit.currency)}</strong></span></div><footer className="ta-ops-editor-actions">{edit.status==='draft'?<><Button disabled={this.state.busy} onClick={this.closeEditors}>{t('Cancel','إلغاء')}</Button><Button icon="save" disabled={this.state.busy} onClick={()=>void this.savePurchase()}>{t('Save Draft','حفظ المسودة')}</Button><Button icon="check" variant="primary" disabled={this.state.busy} onClick={this.postPurchase}>{this.state.busy?t('Working…','جارٍ التنفيذ…'):t('Post Purchase','ترحيل الشراء')}</Button></>:edit.status==='posted'?<Button variant="danger" disabled={this.state.busy} onClick={()=>this.reversePurchase(edit)}>{t('Reverse Purchase','عكس الشراء')}</Button>:<Button disabled={this.state.busy} onClick={this.closeEditors}>{t('Close','إغلاق')}</Button>}</footer></aside>;
  };

  private renderExpenses():any{
    const list=[...this.props.expenses].sort((a,b)=>b.date.localeCompare(a.date)||b.updatedAt.localeCompare(a.updatedAt)).filter(e=>this.visible(e.description,e.category,expenseCategoryLabel(e.category),e.reference,e.currency)),edit=this.state.expenseEdit;
    return <div className="ta-ops-split"><section className="ta-ops-list-card">{this.panelHead(t('Operating costs','المصاريف التشغيلية'),t('Expenses','المصروفات'),t('Operating expenses stay separate from invoice revenue and purchase landed cost.','المصروفات التشغيلية تبقى منفصلة عن إيراد الفواتير وتكلفة وصول المشتريات.'),<Button icon="plus" variant="primary" disabled={this.state.busy} onClick={()=>this.startExpense()}>{t('New Expense','مصروف جديد')}</Button>)}<div className="ta-ops-list">{list.length?list.map(e=><article key={e.id} className="ta-ops-row"><span className="ta-ops-row-icon"><Icon name="invoice"/></span><div className="ta-ops-row-copy"><strong>{e.description}</strong><small>{e.date} · {expenseCategoryLabel(e.category)} · {formatMoney(e.amount,e.currency)}</small></div><div className="ta-ops-row-actions"><button disabled={this.state.busy} onClick={()=>this.startExpense(e)}>{t('Edit','تعديل')}</button><button disabled={this.state.busy} className="is-danger" onClick={()=>this.deleteExpense(e)}>{t('Delete','حذف')}</button></div></article>):this.emptyState('invoice',t('No expenses yet.','لا توجد مصروفات بعد.'),t('Operating expenses will appear here.','ستظهر المصروفات التشغيلية هنا.'))}</div></section>{edit?this.renderExpenseEditor(edit):null}</div>;
  }

  private renderExpenseEditor=(edit:ExpenseRecord)=> <aside className="ta-ops-editor"><header className="ta-ops-editor-head"><div><small>{t('Operating cost','مصروف تشغيلي')}</small><h2>{t('Expense','المصروف')}</h2></div><button type="button" disabled={this.state.busy} aria-label={t('Close editor','إغلاق المحرر')} onClick={this.closeEditors}><Icon name="x"/></button></header><div className="ta-ops-editor-scroll"><div className="ta-ops-form-grid"><label>{t('Date','التاريخ')}<Input type="date" value={edit.date} onChange={(e:any)=>this.setState({expenseEdit:{...edit,date:e.target.value}})}/></label><label>{t('Category','التصنيف')}<Select value={edit.category} onChange={(e:any)=>this.setState({expenseEdit:{...edit,category:e.target.value}})}>{expenseCategories.map(c=><option key={c} value={c}>{expenseCategoryLabel(c)}</option>)}</Select></label><label className="is-wide">{t('Description','الوصف')}<Input value={edit.description} onChange={(e:any)=>this.setState({expenseEdit:{...edit,description:e.target.value}})}/></label><label>{t('Amount','المبلغ')}<Input inputMode="decimal" value={edit.amount} onChange={(e:any)=>this.setState({expenseEdit:{...edit,amount:e.target.value}})}/></label><label>{t('Currency','العملة')}<Input list="operations-currencies" value={edit.currency} onChange={(e:any)=>this.setState({expenseEdit:{...edit,currency:e.target.value.toUpperCase()}})}/></label><label>{t('Supplier (optional)','المورد (اختياري)')}<Select value={edit.supplierId} onChange={(e:any)=>this.setState({expenseEdit:{...edit,supplierId:e.target.value}})}><option value="">—</option>{this.props.suppliers.map(s=><option key={s.id} value={s.id}>{supplierLabel(s)}</option>)}</Select></label><label>{t('Reference','المرجع')}<Input value={edit.reference} onChange={(e:any)=>this.setState({expenseEdit:{...edit,reference:e.target.value}})}/></label><label className="is-wide">{t('Notes','ملاحظات')}<Textarea value={edit.notes} onChange={(e:any)=>this.setState({expenseEdit:{...edit,notes:e.target.value}})}/></label></div></div><footer className="ta-ops-editor-actions"><Button disabled={this.state.busy} onClick={this.closeEditors}>{t('Cancel','إلغاء')}</Button><Button icon="save" variant="primary" disabled={this.state.busy} onClick={()=>void this.saveExpense()}>{this.state.busy?t('Saving…','جارٍ الحفظ…'):t('Save Expense','حفظ المصروف')}</Button></footer></aside>;

  private renderInventory():any{
    const view=this.props.inventoryView??'all',balances=inventoryBalances(this.props.items,this.props.inventoryMovements).filter(row=>this.visible(row.item.sku??'',row.item.descriptionEn,row.item.descriptionAr,row.quantity)),movements=[...this.props.inventoryMovements].sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt.localeCompare(a.createdAt)).slice(0,80).filter(m=>this.visible(m.sku||'',m.itemNameEn||'',m.itemNameAr||'',m.sourceNumber||'',m.note||''));
    return <div className={`ta-inventory-workspace view-${view}`}>{view!=='movements'?<section className="ta-ops-list-card ta-inventory-ledger">{this.panelHead(t('Stock position','وضع المخزون'),t('Inventory Ledger','سجل المخزون'),t('Stock changes only from posted purchases or explicit manual movements. Invoices do not silently change stock.','يتغير المخزون فقط من المشتريات المرحلة أو الحركات اليدوية الصريحة. الفواتير لا تغيّر المخزون تلقائيًا.'))}<div className="ta-inventory-table"><div className="ta-inventory-head"><span>{t('Item','الصنف')}</span><span>{t('On hand','المتوفر')}</span><span>{t('Last landed cost','آخر تكلفة وصول')}</span></div>{balances.length?balances.map(row=><div className={`ta-inventory-row ${row.quantityScaled<0n?'is-negative':''}`} key={row.item.id}><span><strong>{itemLabel(row.item)}</strong><small>{row.item.category||t('Uncategorized','بدون تصنيف')}</small></span><strong>{row.quantity} {row.item.unit}</strong><span>{row.item.lastUnitCost&&row.item.lastCostCurrency?formatMoney(row.item.lastUnitCost,row.item.lastCostCurrency):'—'}</span></div>):this.emptyState('items',t('No saved items yet.','لا توجد أصناف محفوظة بعد.'),t('Add products to begin tracking inventory.','أضف المنتجات لبدء تتبع المخزون.'))}</div></section>:null}
      {view!=='balances'?<div className="ta-inventory-movement-grid"><section className="ta-ops-list-card ta-inventory-entry">{this.panelHead(t('Inventory control','ضبط المخزون'),t('Manual Movement','حركة يدوية'),t('Record an opening balance, issue or explicit adjustment.','سجّل رصيدًا افتتاحيًا أو إخراجًا أو تسوية صريحة.'))}<div className="ta-ops-form-grid"><label className="is-wide">{t('Saved item','الصنف المحفوظ')}<Select value={this.state.movementItemId} onChange={(e:any)=>this.setState({movementItemId:e.target.value})}><option value="">{t('Choose item','اختر الصنف')}</option>{this.props.items.map(item=><option key={item.id} value={item.id}>{itemLabel(item)}</option>)}</Select></label><label>{t('Type','النوع')}<Select value={this.state.movementType} onChange={(e:any)=>this.setState({movementType:e.target.value})}><option value="opening">{t('Opening stock','رصيد افتتاحي')}</option><option value="issue">{t('Stock issue','إخراج مخزون')}</option><option value="adjustment">{t('Adjustment (+/-)','تسوية (+/-)')}</option></Select></label><label>{t('Date','التاريخ')}<Input type="date" value={this.state.movementDate} onChange={(e:any)=>this.setState({movementDate:e.target.value})}/></label><label>{t('Quantity','الكمية')}<Input inputMode="decimal" value={this.state.movementQuantity} onChange={(e:any)=>this.setState({movementQuantity:e.target.value})}/></label><label>{t('Unit cost (optional)','تكلفة الوحدة (اختياري)')}<Input inputMode="decimal" value={this.state.movementCost} onChange={(e:any)=>this.setState({movementCost:e.target.value})}/></label><label>{t('Currency','العملة')}<Input list="operations-currencies" value={this.state.movementCurrency} onChange={(e:any)=>this.setState({movementCurrency:e.target.value.toUpperCase()})}/></label><label className="is-wide">{t('Note','ملاحظة')}<Input value={this.state.movementNote} onChange={(e:any)=>this.setState({movementNote:e.target.value})}/></label></div><div className="ta-inventory-entry-action"><Button icon="plus" variant="primary" disabled={this.state.busy} onClick={()=>void this.saveMovement()}>{this.state.busy?t('Working…','جارٍ التنفيذ…'):t('Record Movement','تسجيل الحركة')}</Button></div></section>
      <section className="ta-ops-list-card ta-inventory-history">{this.panelHead(t('Audit trail','سجل التدقيق'),t('Recent Movements','الحركات الأخيرة'),t('Purchase receipts, reversals and manual inventory changes.','استلامات الشراء والعكس وحركات المخزون اليدوية.'))}<div className="ta-ops-list">{movements.length?movements.map(m=><article key={m.id} className="ta-ops-row"><span className="ta-ops-row-icon"><Icon name="items"/></span><div className="ta-ops-row-copy"><strong>{movementItemLabel(m)}</strong><small>{m.date} · {movementTypeLabel(m.type)}{m.sourceNumber?` · ${m.sourceNumber}`:''}</small></div><strong className={`ta-inventory-quantity ${m.quantity.startsWith('-')?'is-negative':'is-positive'}`}>{m.quantity}</strong>{inventoryMovementIsManual(m)?<div className="ta-ops-row-actions"><button disabled={this.state.busy} className="is-danger" onClick={()=>this.deleteMovement(m)}>{t('Reverse','عكس')}</button></div>:null}</article>):this.emptyState('items',t('No inventory movements yet.','لا توجد حركات مخزون بعد.'),t('Posted purchases and manual movements will appear here.','ستظهر المشتريات المرحلة والحركات اليدوية هنا.'))}</div></section></div>:null}</div>;
  }

  private emptyState=(icon:any,title:string,description:string)=><div className="ta-ops-empty"><span><Icon name={icon}/></span><strong>{title}</strong><small>{description}</small></div>;

  render():any{
    const mode=this.props.mode??'all',allowedTabs=tabsForMode(mode),heading=this.heading();
    return <><section className={`ta-operations-page mode-${mode}`} aria-busy={this.state.busy}><datalist id="operations-currencies">{currencies.map(c=><option key={c} value={c}/>)}</datalist>
      <header className="ta-ops-page-header"><div><span>{heading.eyebrow}</span><h1>{heading.title}</h1><p>{heading.description}</p></div><div className="ta-ops-search"><Icon name="search"/><Input type="search" aria-label={t('Search this workspace','بحث في مساحة العمل')} value={this.state.search} placeholder={t('Search this workspace…','ابحث في مساحة العمل…')} onChange={(e:any)=>this.setState({search:e.target.value})}/>{this.state.search?<button type="button" aria-label={t('Clear search','مسح البحث')} onClick={()=>this.setState({search:''})}><Icon name="x"/></button>:null}</div></header>
      {this.renderSummary()}
      {allowedTabs.length>1?<div className="ta-ops-tabs" role="tablist" aria-label={t('Workspace sections','أقسام مساحة العمل')}>{allowedTabs.map(tab=><button type="button" disabled={this.state.busy} key={tab} id={`operations-tab-${tab}`} role="tab" aria-selected={this.state.tab===tab} aria-controls={`operations-panel-${tab}`} className={this.state.tab===tab?'is-active':''} onClick={()=>this.changeTab(tab)}><span>{tab==='suppliers'?t('Suppliers','الموردون'):tab==='purchases'?t('Purchases','المشتريات'):tab==='expenses'?t('Expenses','المصروفات'):t('Inventory','المخزون')}</span><b aria-hidden="true"/></button>)}</div>:null}
      {this.state.error?<div className="ta-ops-error" role="alert"><span><Icon name="alert"/></span><div><strong>{t('Action needs attention','الإجراء يحتاج انتباهك')}</strong><small>{this.state.error}</small></div><button type="button" aria-label={t('Dismiss error','إغلاق الخطأ')} onClick={this.clearError}><Icon name="x"/></button></div>:null}
      <div className="ta-ops-panel" id={`operations-panel-${this.state.tab}`} role="tabpanel" aria-labelledby={`operations-tab-${this.state.tab}`}>{this.state.tab==='suppliers'?this.renderSuppliers():this.state.tab==='purchases'?this.renderPurchases():this.state.tab==='expenses'?this.renderExpenses():this.renderInventory()}</div>
    </section>{this.renderActionDialogs()}</>;
  }
}
